import sys, os, subprocess, ctypes

SO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_csvsum_fast.so")

C_SRC = r"""
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/wait.h>

#define HT_SIZE 16384
#define HT_MASK (HT_SIZE - 1)

typedef struct {
    char key[64];
    uint32_t len;
    uint32_t used;
    double sum;
} Entry;

static inline uint32_t hash_bytes(const char *s, size_t len) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < len; i++) {
        h = (h ^ (uint8_t)s[i]) * 16777619u;
    }
    return h;
}

static void process_chunk(const char *p, const char *end, Entry *ht) {
    while (p < end) {
        while (p < end && *p != ',') p++;
        p++;
        if (p >= end) break;
        const char *cat_start = p;
        while (p < end && *p != ',') p++;
        size_t cat_len = (size_t)(p - cat_start);
        p++;
        if (p >= end) break;

        int sign = 1;
        if (*p == '-') { sign = -1; p++; }
        else if (*p == '+') { p++; }

        long long int_part = 0;
        while (p < end && *p >= '0' && *p <= '9') {
            int_part = int_part * 10 + (*p - '0');
            p++;
        }
        double val = (double)int_part;
        if (p < end && *p == '.') {
            p++;
            long long frac_part = 0;
            double div = 1.0;
            while (p < end && *p >= '0' && *p <= '9') {
                frac_part = frac_part * 10 + (*p - '0');
                div *= 10.0;
                p++;
            }
            val += (double)frac_part / div;
        }
        if (sign < 0) val = -val;
        while (p < end && *p != '\n') p++;
        if (p < end && *p == '\n') p++;

        uint32_t idx = hash_bytes(cat_start, cat_len) & HT_MASK;
        while (1) {
            if (!ht[idx].used) {
                ht[idx].used = 1;
                ht[idx].len = (uint32_t)cat_len;
                memcpy(ht[idx].key, cat_start, cat_len);
                ht[idx].key[cat_len] = '\0';
                ht[idx].sum = val;
                break;
            }
            if (ht[idx].len == cat_len && memcmp(ht[idx].key, cat_start, cat_len) == 0) {
                ht[idx].sum += val;
                break;
            }
            idx = (idx + 1) & HT_MASK;
        }
    }
}

static int cmp_entry(const void *a, const void *b) {
    const Entry *ea = *(const Entry **)a;
    const Entry *eb = *(const Entry **)b;
    return strcmp(ea->key, eb->key);
}

int run_csvsum(void) {
    struct stat st;
    if (fstat(0, &st) != 0 || st.st_size <= 0) return -1;
    size_t n = (size_t)st.st_size;
    const char *mm = (const char *)mmap(NULL, n, PROT_READ, MAP_PRIVATE, 0, 0);
    if (mm == MAP_FAILED) return -1;

    size_t start0 = 0;
    while (start0 < n && mm[start0] != '\n') start0++;
    if (start0 < n) start0++;

    const int W = 8;
    size_t bounds[W + 1];
    bounds[0] = start0;
    for (int i = 1; i < W; i++) {
        size_t pos = start0 + (n - start0) * i / W;
        while (pos < n && mm[pos] != '\n') pos++;
        if (pos < n) pos++;
        bounds[i] = pos;
    }
    bounds[W] = n;

    int pipes[W][2];
    pid_t pids[W];
    for (int i = 1; i < W; i++) {
        pipe(pipes[i]);
        pid_t pid = fork();
        if (pid == 0) {
            close(pipes[i][0]);
            Entry *ht = (Entry *)calloc(HT_SIZE, sizeof(Entry));
            process_chunk(mm + bounds[i], mm + bounds[i+1], ht);
            for (int j = 0; j < HT_SIZE; j++) {
                if (ht[j].used) {
                    write(pipes[i][1], &ht[j], sizeof(Entry));
                }
            }
            close(pipes[i][1]);
            _exit(0);
        }
        close(pipes[i][1]);
        pids[i] = pid;
    }

    Entry *ht = (Entry *)calloc(HT_SIZE, sizeof(Entry));
    process_chunk(mm + bounds[0], mm + bounds[1], ht);

    for (int i = 1; i < W; i++) {
        Entry e;
        while (read(pipes[i][0], &e, sizeof(Entry)) == sizeof(Entry)) {
            uint32_t idx = hash_bytes(e.key, e.len) & HT_MASK;
            while (1) {
                if (!ht[idx].used) {
                    ht[idx] = e;
                    break;
                }
                if (ht[idx].len == e.len && memcmp(ht[idx].key, e.key, e.len) == 0) {
                    ht[idx].sum += e.sum;
                    break;
                }
                idx = (idx + 1) & HT_MASK;
            }
        }
        close(pipes[i][0]);
        waitpid(pids[i], NULL, 0);
    }

    Entry *list[HT_SIZE];
    int count = 0;
    for (int j = 0; j < HT_SIZE; j++) {
        if (ht[j].used) list[count++] = &ht[j];
    }
    qsort(list, count, sizeof(Entry *), cmp_entry);

    for (int i = 0; i < count; i++) {
        printf("%s,%.2f\n", list[i]->key, list[i]->sum);
    }
    fflush(stdout);
    free(ht);
    munmap((void *)mm, n);
    return 0;
}
"""

def ensure_so():
    if not os.path.exists(SO_PATH):
        c_path = SO_PATH + f".{os.getpid()}.c"
        tmp_so = SO_PATH + f".{os.getpid()}.so"
        with open(c_path, "w") as f:
            f.write(C_SRC)
        subprocess.run(["gcc", "-O3", "-shared", "-fPIC", c_path, "-o", tmp_so], check=True)
        os.replace(tmp_so, SO_PATH)
        os.remove(c_path)

def main():
    ensure_so()
    lib = ctypes.CDLL(SO_PATH)
    if lib.run_csvsum() != 0:
        # Fallback for non-seekable pipe stdin
        from collections import defaultdict
        sums = defaultdict(float)
        sys.stdin.buffer.readline()
        for line in sys.stdin.buffer:
            _, cat, val = line.split(b',')
            sums[cat] += float(val)
        out = [f"{cat.decode()},{sums[cat]:.2f}\n" for cat in sorted(sums)]
        sys.stdout.write("".join(out))

if __name__ == '__main__':
    main()
